package bookmarksapi

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
)

func do(t *testing.T, s *Server, method, path, body string) (int, string) {
	var rd io.Reader
	if body != "" {
		rd = strings.NewReader(body)
	}
	req := httptest.NewRequest(method, path, rd)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	b, _ := io.ReadAll(rec.Result().Body)
	return rec.Code, string(b)
}

func TestSmoke(t *testing.T) {
	s := NewServer()
	// create
	code, body := do(t, s, "POST", "/bookmarks", `{"url":"https://a.com","title":"A","tags":["x","y"]}`)
	if code != 201 {
		t.Fatalf("create: %d %s", code, body)
	}
	var b1 Bookmark
	json.Unmarshal([]byte(body), &b1)
	if b1.ID != "1" || b1.Visits != 0 {
		t.Fatalf("b1 = %+v", b1)
	}
	// missing url
	if c, _ := do(t, s, "POST", "/bookmarks", `{"title":"x"}`); c != 400 {
		t.Fatalf("missing url: %d", c)
	}
	// invalid json
	if c, _ := do(t, s, "POST", "/bookmarks", `{bad`); c != 400 {
		t.Fatalf("bad json: %d", c)
	}
	// tags not array
	if c, _ := do(t, s, "POST", "/bookmarks", `{"url":"u","tags":"nope"}`); c != 400 {
		t.Fatalf("tags not array: %d", c)
	}
	// second create, no tags -> []
	c2, b2 := do(t, s, "POST", "/bookmarks", `{"url":"https://b.com"}`)
	if c2 != 201 {
		t.Fatalf("create2: %d %s", c2, b2)
	}
	if !strings.Contains(b2, `"tags":[]`) {
		t.Fatalf("tags not []: %s", b2)
	}
	// get
	c3, b3 := do(t, s, "GET", "/bookmarks/2", "")
	if c3 != 200 || !strings.Contains(b3, `"id":"2"`) {
		t.Fatalf("get: %d %s", c3, b3)
	}
	if c4, _ := do(t, s, "GET", "/bookmarks/99", ""); c4 != 404 {
		t.Fatalf("get 404: %d", c4)
	}
	// visit
	c5, b5 := do(t, s, "POST", "/bookmarks/1/visit", "")
	if c5 != 200 || !strings.Contains(b5, `"visits":1`) {
		t.Fatalf("visit: %d %s", c5, b5)
	}
	if c6, _ := do(t, s, "POST", "/bookmarks/99/visit", ""); c6 != 404 {
		t.Fatalf("visit 404: %d", c6)
	}
	// list order: 1 (visits=1) before 2 (visits=0)
	c7, b7 := do(t, s, "GET", "/bookmarks", "")
	if c7 != 200 || !strings.Contains(b7, `"id":"1"`) || strings.Index(b7, `"id":"1"`) > strings.Index(b7, `"id":"2"`) {
		t.Fatalf("list: %d %s", c7, b7)
	}
	// empty list shape
	s2 := NewServer()
	_, le := do(t, s2, "GET", "/bookmarks", "")
	if le != "[]" {
		t.Fatalf("empty list: %q", le)
	}
	// patch title only
	c8, b8 := do(t, s, "PATCH", "/bookmarks/2", `{"title":"New"}`)
	if c8 != 200 || !strings.Contains(b8, `"title":"New"`) || !strings.Contains(b8, `"tags":[]`) {
		t.Fatalf("patch: %d %s", c8, b8)
	}
	// patch tags only
	c9, b9 := do(t, s, "PATCH", "/bookmarks/2", `{"tags":["z"]}`)
	if c9 != 200 || !strings.Contains(b9, `"tags":["z"]`) || !strings.Contains(b9, `"title":"New"`) {
		t.Fatalf("patch tags: %d %s", c9, b9)
	}
	// patch empty title
	if c10, _ := do(t, s, "PATCH", "/bookmarks/2", `{"title":""}`); c10 != 400 {
		t.Fatalf("patch empty title: %d", c10)
	}
	// patch bad json
	if c11, _ := do(t, s, "PATCH", "/bookmarks/2", `{`); c11 != 400 {
		t.Fatalf("patch bad json: %d", c11)
	}
	// patch 404
	if c12, _ := do(t, s, "PATCH", "/bookmarks/99", `{"title":"x"}`); c12 != 404 {
		t.Fatalf("patch 404: %d", c12)
	}
	// delete
	c13, _ := do(t, s, "DELETE", "/bookmarks/2", "")
	if c13 != 204 {
		t.Fatalf("delete: %d", c13)
	}
	if c14, _ := do(t, s, "DELETE", "/bookmarks/2", ""); c14 != 404 {
		t.Fatalf("delete 404: %d", c14)
	}
	// unknown method/path
	if c15, _ := do(t, s, "PUT", "/bookmarks", ""); c15 != 404 {
		t.Fatalf("put: %d", c15)
	}
	if c16, _ := do(t, s, "GET", "/nope", ""); c16 != 404 {
		t.Fatalf("get /nope: %d", c16)
	}
	// error body has "error" key
	_, eb := do(t, s, "GET", "/bookmarks/99", "")
	var em map[string]string
	if err := json.Unmarshal([]byte(eb), &em); err != nil || em["error"] == "" {
		t.Fatalf("error body: %s", eb)
	}
	// concurrency
	s3 := NewServer()
	_, cb := do(t, s3, "POST", "/bookmarks", `{"url":"u"}`)
	json.Unmarshal([]byte(cb), &b1)
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			do(t, s3, "POST", "/bookmarks/1/visit", "")
		}()
	}
	wg.Wait()
	_, vb := do(t, s3, "GET", "/bookmarks/1", "")
	if !strings.Contains(vb, `"visits":100`) {
		t.Fatalf("concurrent visits: %s", vb)
	}
	fmt.Println("smoke ok")
}
EOF
