import 'dart:convert';
import 'package:bookmarks_client/bookmarks_client.dart';
import 'package:bookmarks_client/bookmarks_view_model.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:test/test.dart';

void main() {
  test('Bookmark json round trip', () {
    final b = Bookmark(id: '1', url: 'u', title: 't', tags: ['a'], visits: 2);
    final j = b.toJson();
    expect(j.keys.toSet(), {'id', 'url', 'title', 'tags', 'visits'});
    final c = Bookmark.fromJson(jsonDecode(jsonEncode(j)));
    expect(c.id, '1');
    expect(c.tags, ['a']);
    expect(c.visits, 2);
  });

  test('client methods hit right routes and parse', () async {
    Map<String, dynamic>? lastBody;
    String? lastMethod, lastPath;
    final mock = MockClient((req) async {
      lastMethod = req.method;
      lastPath = req.url.path;
      lastBody = req.body.isEmpty ? null : jsonDecode(req.body) as Map<String, dynamic>;
      if (req.method == 'POST' && req.url.path == '/bookmarks') {
        return http.Response(
            jsonEncode({'id': '1', 'url': 'u', 'title': 't', 'tags': ['a'], 'visits': 0}), 201,
            headers: {'content-type': 'application/json'});
      }
      if (req.method == 'GET' && req.url.path == '/bookmarks') {
        return http.Response(
            jsonEncode([
              {'id': '2', 'url': 'u2', 'title': '', 'tags': [], 'visits': 3}
            ]),
            200);
      }
      if (req.method == 'PATCH') {
        return http.Response(
            jsonEncode({'id': '1', 'url': 'u', 'title': 'nt', 'tags': ['a'], 'visits': 0}), 200);
      }
      if (req.method == 'DELETE') {
        return http.Response('', 204);
      }
      if (req.url.path == '/bookmarks/99') {
        return http.Response(jsonEncode({'error': 'bookmark not found'}), 404);
      }
      return http.Response(
          jsonEncode({'id': '1', 'url': 'u', 'title': 't', 'tags': ['a'], 'visits': 1}), 200);
    });
    final c = BookmarksApiClient('http://x', httpClient: mock);

    final created = await c.createBookmark(url: 'u', title: 't', tags: ['a']);
    expect(lastMethod, 'POST');
    expect(lastPath, '/bookmarks');
    expect(lastBody, {'url': 'u', 'title': 't', 'tags': ['a']});
    expect(created.id, '1');

    final list = await c.listBookmarks();
    expect(list.single.id, '2');
    expect(list.single.visits, 3);

    final visited = await c.visitBookmark('1');
    expect(lastMethod, 'POST');
    expect(lastPath, '/bookmarks/1/visit');
    expect(visited.visits, 1);

    final updated = await c.updateBookmark('1', title: 'nt');
    expect(lastMethod, 'PATCH');
    expect(lastBody, {'title': 'nt'}); // tags omitted
    expect(updated.title, 'nt');

    await c.deleteBookmark('1');
    expect(lastMethod, 'DELETE');
    expect(lastPath, '/bookmarks/1');

    await expectLater(c.getBookmark('99'),
        throwsA(isA<BookmarksApiException>().having((e) => e.statusCode, 'code', 404)
            .having((e) => e.message, 'msg', 'bookmark not found')));
  });

  test('view model behavior', () async {
    final mock = MockClient((req) async {
      if (req.method == 'GET') {
        return http.Response(jsonEncode([
          {'id': '1', 'url': 'u1', 'title': '', 'tags': ['b'], 'visits': 0},
          {'id': '2', 'url': 'u2', 'title': '', 'tags': ['a', 'b'], 'visits': 2},
        ]), 200);
      }
      if (req.method == 'POST' && req.url.path.endsWith('/visit')) {
        return http.Response(jsonEncode({'id': '1', 'url': 'u1', 'title': '', 'tags': ['b'], 'visits': 1}), 200);
